EXCEPTION
    WHEN OTHERS THEN
        p_mensaje_resultado := 'ERROR: ' || SQLERRM;
END;
$procedure$

fn_calcular_porcentaje_comision.definition:
CREATE OR REPLACE FUNCTION public.fn_calcular_porcentaje_comision(p_utilidad double precision, p_valor_base double precision)
 RETURNS double precision
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF COALESCE(p_valor_base, 0.0) = 0.0 THEN
        RETURN 0.0;
    END IF;
    RETURN (COALESCE(p_utilidad, 0.0) / p_valor_base) * 100.0;
END;
$function$

