				END IF;

				--IF EXISTS (SELECT * FROM public."SystemParameter" Where code = '565' AND LTRIM(RTRIM(value)) = 'S') THEN
				--	UPDATE public."BookingGDS" SET cd_formapago_cliente = (SELECT c.code_fp 
				--								  FROM public."Configuracion_remisiones_FPago" c
				--								  INNER JOIN public."Configuracion_remisiones" e ON e.id_cliente = c.id_cliente
				--								  WHERE (c.id_cliente = p_client OR c.id_cliente = p_ds_cliid)
				--									AND e.bl_forma_pago = 1
				--									AND c.bl_defecto = 1
				--								  LIMIT 1)
				--	WHERE id = p_Id_BookingGDS;
				--END IF; 

				p_id_out := p_Id_BookingGDS;
				RETURN;
			END IF;
		END IF;
		p_id_out := p_Id_BookingGDS;
		RETURN;
	END IF;

	IF p_Op IN ('flight', 'car', 'hotel', 'insurance', 'product') THEN
		-- Determinamos la nacionalidad si no viene por parametro
		IF p_inNationality IS NULL THEN
			v_inNationality := 1;
			IF EXISTS (SELECT A.id FROM public."Airports" A 
			  INNER JOIN public."Cities" C ON C.id = A."citiesId"
			  INNER JOIN public."Countries" P ON P.id = C."countriesId"
			  INNER JOIN public."SystemParameter" PR ON PR.code = 'Pais' AND PR.value<>P.name 
			  WHERE A.code = COALESCE(p_cd_citysalida, p_origin, p_cd_city, ''))
			THEN
				v_inNationality := 2;
			ELSE
				v_inNationality := 1;
			END IF;
		ELSE
			v_inNationality := p_inNationality;
		END IF;

		-- 1. Insertamos el Producto
		INSERT INTO public."BookingProductGDS" (
			"bookingId", code, type, "service", "description", 
			"prestadoracode", "prestadorainitials", "prestadoradist", "provider", 
			"quantity", price, cost, "checkInDate", "checkOutDate", 
			"nights", "paxAdults", "paxChildren", "serviceType", "billingConcept", 
			"destination", "reservationCode", "sellerCom", "ticketPrinterCom", 
			"inNationality", "state", "conjunction", "revised", "typeproduct", "penalty", consecutive
		) VALUES (
			p_bookingId, 
			COALESCE(p_code, ''), 
			COALESCE(p_productType, CASE WHEN p_Op = 'flight' THEN 'Tiquete' WHEN p_Op = 'car' THEN 'car' WHEN p_Op = 'hotel' THEN 'hotel' WHEN p_Op = 'insurance' THEN 'insurance' ELSE '' END), 
			COALESCE(p_productService, CASE WHEN p_Op = 'flight' THEN 'Tiquete Aereo' WHEN p_Op = 'car' THEN 'Renta de Auto' WHEN p_Op = 'hotel' THEN 'Alojamiento' WHEN p_Op = 'insurance' THEN 'Seguros' ELSE '' END), 
			COALESCE(p_productDescription, CASE WHEN p_Op = 'flight' THEN 'Emision de Tiquete' WHEN p_Op = 'car' THEN 'Servicio de Renta de Auto' WHEN p_Op = 'hotel' THEN 'Reserva de Hotel' WHEN p_Op = 'insurance' THEN 'Servicio de seguros' ELSE '' END),
			p_prestadoraCode, 
			p_prestadoraInitials, 
			p_prestadoraDist, 
			p_provider,
			COALESCE(p_quantity, 1), 
			COALESCE(p_amount, 0), 
			COALESCE(p_cost, 0), 
			p_checkInDate, 
			p_checkOutDate, 
			p_nights, 
			p_paxAdults, 
			p_paxChildren, 
			p_serviceType, 
			p_billingConcept, 
			p_destination, 
			p_code, 
			p_sellerCom, 
			p_ticketPrinterCom, 
			v_inNationality, 
			COALESCE(p_status, 'NUEVO'), 
			p_conjunction, 
			p_revised, 
			p_typeproduct, 
			p_penalty,
			p_consecutive
		) RETURNING id INTO v_BookingProductId;

		-- 2. Insertamos el Pasajero (Solo si viene en el mismo llamado)
		--IF COALESCE(p_firstName, '') <> '' THEN
		--	INSERT INTO public."BookingProductPassangerGDS" (
		--		"bookingProductId", "firstnm", "lastnm", "prefix", "identification", "phone", "email"
		--	) VALUES (
		--		v_BookingProductId, p_firstName, p_lastName, p_documentType, p_identification, p_phone, p_email
		--	);
		--END IF;

		p_id_out := v_BookingProductId;
		RETURN;
	END IF;


	IF p_Op = 'itinerary' THEN
		v_fecha_salida := p_ds_fecha_salida;
		-- Lógica de ajuste de año (legacy)
		IF LENGTH(v_fecha_salida) >= 8 THEN
			v_Y := SUBSTRING(v_fecha_salida, 1, 4);
			v_M := SUBSTRING(v_fecha_salida, 5, 2);
			v_D := SUBSTRING(v_fecha_salida, 7, 2);
			SELECT EXTRACT(MONTH FROM "date")::INTEGER, EXTRACT(YEAR FROM "date")::INTEGER 
			INTO v_Mr, v_YAr
			FROM public."BookingGDS" WHERE id = p_bookingId;

			IF (v_Mr > v_M::INTEGER AND v_YAr >= v_Y::INTEGER) THEN
				v_Yr := v_Y::INTEGER + 1;
				v_Y := v_Yr::TEXT;
			END IF;

			v_fecha_salida := v_Y || LPAD(v_M, 2, '0') || LPAD(v_D, 2, '0');
		END IF;

		-- Construir Timestamps
		v_checkIn := TO_TIMESTAMP(v_fecha_salida || ' ' || COALESCE(p_ds_hora_salida, '00:00'), 'YYYYMMDD HH24:MI');
		v_checkOut := TO_TIMESTAMP(v_fecha_salida || ' ' || COALESCE(p_ds_hora_llegada, '00:00'), 'YYYYMMDD HH24:MI');
		INSERT INTO public."BookingProductItineraryGDS" (
			"bookingProductId",
			"orden",
			"origin",
			"destination",
			"class",
			"checkInDate",
			"checkOutDate",
			"terminal",
			"prestadoraCode",
			"farebasis",
			"Numflight",
			"Typeflight",
			"amount"
		) VALUES (
			COALESCE(p_bookingProductId, (SELECT MAX(id) FROM public."BookingProductGDS" WHERE "bookingId" = p_bookingId)),
			p_orden,
			p_origin,
			p_destination,
			LEFT(p_class, 1),
			v_checkIn,
			v_checkOut,
			COALESCE(p_terminal, p_destination), -- terminal
			COALESCE(p_prestadoraCode, ''),
			COALESCE(p_farebasis, ''),
			p_Numflight,
			p_Typeflight,
			COALESCE(p_amount, 0)
		);

		p_id_out := p_bookingId;
		RETURN;
	END IF;


	--IF p_Op = 'Poliza' THEN
	--	INSERT INTO public."BookingProductVariableGDS"("bookingProductId", code, name, "value")
	--	VALUES (p_bookingProductId, 'POLIZA', 'Poliza', COALESCE(p_policy, ''));
	--END IF;

	IF p_Op IN ('passanger') THEN
		INSERT INTO public."BookingProductPassangerGDS"("bookingProductId", "firstnm", "lastnm", "prefix", "identification", "phone", "email")
		VALUES (COALESCE(p_bookingProductId, (SELECT MAX(id) FROM public."BookingProductGDS" WHERE "bookingId" = p_bookingId)), p_firstName, p_lastName, p_documentType, p_identification, p_phone, p_email);

		p_id_out := p_bookingId;
		RETURN;
	END IF;

	IF p_Op = 'var' THEN 
		INSERT INTO public."BookingProductVariableGDS"("bookingProductId", code, name, "value")
		VALUES (p_bookingProductId, COALESCE(p_varName, 'VAR'), p_varName, p_varValue);
	END IF;

	IF p_Op = 'tax' THEN
		INSERT INTO public."BookingProductTaxGDS"("bookingProductId", code, name, type, ismain, percentage, amount)
		VALUES (p_bookingProductId, COALESCE(p_taxCode, 'TAX'), COALESCE(p_taxName, 'Impuesto'), COALESCE(p_taxType, 'IMP'), p_taxismain, COALESCE(p_perTax, 0), p_tax);
	END IF;

	IF p_Op = 'payment' THEN
		INSERT INTO public."BookingProductPaymentGDS"(
			"bookingProductId", code, name, type, "typecreditcard", "numbercreditcard", 
			"vouchercreditcard", "expiredcreditcard", "authcreditcard", "quotas", 
			"bank", "square", "reference", "policy", "policyannex", amount
		)
		VALUES (
			p_bookingProductId, COALESCE(p_paymentCode, 'PAG'), COALESCE(p_paymentName, 'Pago'), COALESCE(p_paymentType, 'EFECTIVO'), p_creditCardType, p_creditCardNumber, 
			p_voucher, p_expirationDate, p_authorization, p_quotas, 
			p_bank, p_square, p_reference, p_policy, p_policyAnnex, p_amount
		);
	END IF;

	IF p_Op = 'FEE' THEN
		INSERT INTO public."BookingProductFEEGDS"(
			"bookingProductId", code, name, type, "description", "billigconcept", "servicetype", amount, tax, other, total
		)
		VALUES (
			p_bookingProductId, COALESCE(p_feeCode, 'FEE'), COALESCE(p_feeName, 'Fee'), COALESCE(p_feeType, 'FEE'), COALESCE(p_feeDescription, ''), 
			COALESCE(p_feeBillingConcept, '1'), COALESCE(p_feeServiceType, '1'), p_amount, 0, 0, p_amount
		);
	END IF;

	p_id_out := NULL;
	RETURN;
END;
$procedure$

spmonedaeliminar.definition:
CREATE OR REPLACE PROCEDURE public.spmonedaeliminar(IN p_id integer, IN p_acting_user_id integer, INOUT p_mensaje_resultado text)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public."Currency" WHERE id = p_id) THEN
        p_mensaje_resultado := 'ERROR: Moneda con ID ' || p_id || ' no encontrada';
        RETURN;
    END IF;

    DELETE FROM public."Currency" WHERE id = p_id;

    p_mensaje_resultado := 'SUCCESS: Moneda ' || p_id || ' eliminada correctamente';
EXCEPTION
    WHEN OTHERS THEN
        p_mensaje_resultado := 'ERROR: ' || SQLERRM;
END;
$procedure$

spprestadoraeliminar.definition:
CREATE OR REPLACE PROCEDURE public.spprestadoraeliminar(IN p_id integer, IN p_acting_user_id integer, INOUT p_mensaje_resultado text)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
    DELETE FROM public."Prestadora" WHERE id = p_id;
    p_mensaje_resultado := 'SUCCESS: Prestadora eliminado.';
EXCEPTION
    WHEN OTHERS THEN
        p_mensaje_resultado := 'ERROR: ' || SQLERRM;
END;
$procedure$

spPaymentActualizar.definition:
CREATE OR REPLACE PROCEDURE public."spPaymentActualizar"(IN p_id integer, IN p_code text, IN p_name text, IN p_iscash boolean, IN p_iscredit boolean, IN p_inactive boolean, IN p_user_id integer, INOUT p_mensaje_resultado text)
 LANGUAGE plpgsql
AS $procedure$
DECLARE v_existente integer;
BEGIN
    SELECT id INTO v_existente FROM public."Payment" WHERE id = p_id;
    IF v_existente IS NULL THEN p_mensaje_resultado := 'ERROR: No existe.'; RETURN; END IF;
    SELECT id INTO v_existente FROM public."Payment" WHERE "code" = p_code AND id <> p_id;
    IF v_existente IS NOT NULL THEN p_mensaje_resultado := 'ERROR: El código ya existe.'; RETURN; END IF;
    UPDATE public."Payment" SET "code" = COALESCE(TRIM(p_code), ''), "name" = TRIM(p_name), "iscash" = COALESCE(p_iscash, false), "iscredit" = COALESCE(p_iscredit, false), "inactive" = COALESCE(p_inactive, false) WHERE id = p_id;
    p_mensaje_resultado := 'SUCCESS';
EXCEPTION WHEN OTHERS THEN p_mensaje_resultado := 'ERROR: ' || SQLERRM; END; $procedure$

spcellcustomizationdelete.definition:
CREATE OR REPLACE PROCEDURE public.spcellcustomizationdelete(IN p_code text, IN p_branch_id integer, IN p_implant_id integer)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
    IF p_branch_id IS NOT NULL THEN
        DELETE FROM public."CellCustomization"
        WHERE "code" = p_code AND "branchId" = p_branch_id AND "implantId" IS NULL;
    ELSIF p_implant_id IS NOT NULL THEN
        DELETE FROM public."CellCustomization"
        WHERE "code" = p_code AND "implantId" = p_implant_id;
    END IF;
END;
$procedure$

spcotizacionactualizarestadomanual.definition:
CREATE OR REPLACE PROCEDURE public.spcotizacionactualizarestadomanual(IN p_quotation_id integer, IN p_state text, IN p_description text, IN p_acting_user_id integer, INOUT p_mensaje_resultado text)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
    -- Validaciones
    IF p_state IS NULL OR p_state = '' THEN
        p_mensaje_resultado := 'ERROR: El estado es obligatorio.';
        RETURN;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public."Quotation" WHERE id = p_quotation_id) THEN
        p_mensaje_resultado := 'ERROR: La cotización con ID ' || p_quotation_id || ' no existe.';
        RETURN;
    END IF;

    -- Validar si el estado existe en la tabla de estados
    IF NOT EXISTS (SELECT 1 FROM public."QuotationState" WHERE code = p_state) THEN
        p_mensaje_resultado := 'ERROR: El estado "' || p_state || '" no es válido.';
        RETURN;
    END IF;

    UPDATE public."Quotation" SET
        "state" = p_state,
        "stateDescription" = p_description,
        "stateUpdatedAt" = CURRENT_TIMESTAMP
    WHERE id = p_quotation_id;

    -- Insertar historial de estado
    INSERT INTO public."QuotationStateHistory" ("quotationId", "state", "description", "createdAt", "userId")
    VALUES (p_quotation_id, p_state, p_description, CURRENT_TIMESTAMP, p_acting_user_id);

    p_mensaje_resultado := 'SUCCESS: Estado de cotización actualizado correctamente.';

    -- Registrar en Auditoría
    CALL public."spLogRegistrar"(
        p_acting_user_id, 
        'QUOTATION', 
        'UPDATE_STATE', 
        'Se cambió el estado de la cotización ID ' || p_quotation_id || ' a ' || p_state || '. Descripción: ' || COALESCE(p_description, ''), 
        jsonb_build_object('quotationId', p_quotation_id, 'state', p_state, 'description', p_description), 
        p_quotation_id
    );

EXCEPTION
    WHEN OTHERS THEN
        p_mensaje_resultado := 'ERROR: ' || SQLERRM;
END;
$procedure$

spimpuestoeliminar.definition:
CREATE OR REPLACE PROCEDURE public.spimpuestoeliminar(IN p_id integer, IN p_acting_user_id integer, INOUT p_mensaje_resultado text)
