CREATE OR REPLACE PROCEDURE public.spclienteactualizar(IN p_id integer, IN p_name text, IN p_document text, IN p_contact_info text, IN p_address text, IN p_mandatory_variables jsonb, IN p_acting_user_id integer, INOUT p_mensaje_resultado text)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
    IF EXISTS (SELECT 1 FROM public."Client" WHERE document = p_document AND id <> p_id) THEN
        p_mensaje_resultado := 'ERROR: El documento ya está registrado por otro cliente.';
        RETURN;
    END IF;

    UPDATE public."Client" SET
        "name" = p_name,
        "document" = p_document,
        "contactInfo" = p_contact_info,
        "address" = p_address,
        "mandatoryVariables" = p_mandatory_variables
    WHERE id = p_id;

    p_mensaje_resultado := 'SUCCESS: Cliente ' || p_id || ' actualizado.';
EXCEPTION
    WHEN OTHERS THEN
        p_mensaje_resultado := 'ERROR: ' || SQLERRM;
        ROLLBACK;
END;
$procedure$

spEquivalencesInterfacesEliminar.definition:
CREATE OR REPLACE PROCEDURE public."spEquivalencesInterfacesEliminar"(IN p_id integer, IN p_user_id integer, INOUT p_success boolean DEFAULT false)
 LANGUAGE plpgsql
AS $procedure$
DECLARE
    v_log_id INT;
BEGIN
    DELETE FROM public."EquivalencesInterfaces"
    WHERE id = p_id;

    IF FOUND THEN
        p_success := true;

        -- Registrar en SystemLog
        CALL public."spLogRegistrar"(
            p_user_id,
            'EQUIVALENCES_INTERFACES',
            'DELETE',
            'Eliminación de equivalencia de interface con ID: ' || p_id,
            jsonb_build_object('id', p_id),
            v_log_id
        );
    ELSE
        p_success := false;
    END IF;
END;
$procedure$

